 {id:'jss3-fe-35',prompt:'If x terms cancel and an equation reduces to1=3, what does that indicate?',options:['x=1','x=3','Every x','No solution'],correctAnswer:'No solution',explanation:'The resulting false statement cannot be satisfied.',difficulty:3,skill:'no-solution'},
 {id:'jss3-fe-36',prompt:'What should be done first in a word problem leading to a fractional equation?',options:['Multiply every number together','Define the unknown and translate the relationships','Guess an answer','Find an LCM before reading the question'],correctAnswer:'Define the unknown and translate the relationships',explanation:'A correct model must be formed before equation solving begins.',difficulty:2,skill:'word-problem-method'}
