export const jss3SimilarShapesTopic='Similar Shapes (enlargement, scale factor, length/area/volume scaling, quantitative reasoning)';

export const jss3SimilarShapesPlan:TutorPlan={
 goal:'Identify and compare similar plane figures and solids, enlarge or reduce them using scale factors, and solve JSS3/BECE problems involving corresponding lengths, areas and volumes.',
 why:'NERDC requires JSS3 learners to identify similar triangles, rectangles, squares, cubes and cuboids; recognize similarity in the environment; enlarge figures using scale factors; calculate lengths, areas and volumes of similar figures; and solve quantitative-reasoning problems.',
 outcomes:[
  'Explain similarity and distinguish it from congruence.',
  'Identify corresponding vertices, angles, sides, edges and dimensions.',
  'Determine whether figures are similar using equal corresponding angles and proportional corresponding lengths.',
  'Find and interpret enlargement and reduction scale factors.',
  'Enlarge or reduce figures and coordinates using a given scale factor.',
  'Calculate unknown corresponding lengths using linear scale factor k.',
  'Use perimeter factor k, area factor k² and volume factor k³.',
  'Work backwards from area or volume ratios to obtain linear scale factors.',
  'Solve problems involving similar triangles, rectangles, squares, cubes and cuboids.',
  'Solve environmental, model, map and quantitative-reasoning problems involving similarity.'
 ],
 examFocus:[
  'Corresponding parts must be matched correctly before forming a ratio.',
  'Keep ratio direction consistent: image/original or larger/smaller.',
  'A linear scale factor k multiplies every corresponding length.',
  'Perimeters scale by k, areas by k², volumes by k³.',
  'To recover length factor from area factor, take a square root; from volume factor, take a cube root.',
  'Similar means same shape/proportions, not necessarily same size; congruent means same shape and same size.',
  'All squares are similar and all cubes are similar, but arbitrary rectangles or cuboids are not automatically similar.',
  'Convert units before comparing corresponding lengths, areas or volumes.',
  'For enlargement/reduction on coordinates about the origin, multiply each coordinate by k.',
  'Check whether a calculated answer is sensible: enlargement k>1 should increase lengths, area and volume.'
 ],
 units:[
  {title:'Meaning of similar shapes',terms:[['similar figures','figures with the same shape: corresponding angles equal and corresponding lengths proportional'],['corresponding','occupying matching positions in two figures']],explain:'Similarity preserves shape but allows size to change. Matching angles stay equal and all matching lengths change in one constant ratio. NERDC expects recognition in triangles, rectangles, squares, cubes and cuboids.',example:'A 3 cm by 5 cm rectangle and a 6 cm by 10 cm rectangle are similar because both corresponding side ratios are2.',check:'Are rectangles 4×6 and6×9 similar? Explain using ratios.',commonMistakes:['deciding by appearance only','checking only one pair of sides','matching a length with a non-corresponding side']},
  {title:'Similar versus congruent',terms:[['congruent','same shape and same size'],['similar','same shape/proportions, possibly different size']],explain:'Congruent figures have scale factor1. Similar figures may have any positive scale factor. Thus every congruent pair is similar, but similar figures need not be congruent.',example:'Triangles with sides3,4,5 and6,8,10 are similar with k=2 but not congruent. Two3-4-5 triangles are congruent and therefore also similar.',check:'What scale factor relates congruent figures?',commonMistakes:['using similar and congruent as synonyms','saying different-sized figures can never be similar','forgetting that k=1 is allowed']},
  {title:'Corresponding vertices, sides and angles',terms:[['corresponding vertices','matching corners'],['corresponding sides','sides joining matching vertices'],['corresponding angles','angles at matching vertices']],explain:'Before calculating, establish the matching order. If △ABC~△PQR, then A↔P,B↔Q,C↔R; AB↔PQ, BC↔QR, AC↔PR. Ratios must use these pairs.',example:'If AB=4,BC=6,AC=8 and PQ=6,QR=9,PR=12, every image/original ratio is3/2.',check:'If △XYZ~△LMN, which side corresponds to YZ?',commonMistakes:['matching by drawing orientation rather than labels','reversing vertex order midway','mixing two ratio directions']},
  {title:'How to test similarity using side ratios',terms:[['proportional','having equal corresponding ratios']],explain:'Compute corresponding length ratios in one direction. If they are all equal and the shape correspondence is valid, the lengths support similarity.',example:'Sides4,6,8 and6,9,12:6/4=9/6=12/8=3/2, so corresponding lengths are proportional.',check:'Test triangles with sides3,5,7 and6,10,14.',commonMistakes:['adding side lengths instead of comparing ratios','using 6/4 for one pair and6/9 for another','rounding ratios too early']},
  {title:'Angles and similarity',terms:[['equal corresponding angles','matching angles with equal measures']],explain:'Similar figures preserve angle measures. For triangles, equal corresponding angles establish the same shape, while side lengths differ by one scale factor. For rectangles, all angles are90°, so equal angles alone do not distinguish their proportions; corresponding side ratios must also agree.',example:'A 2×5 rectangle and4×10 rectangle are similar; a2×5 rectangle and4×8 rectangle are not, even though all angles are90°.',check:'Why are all rectangles not automatically similar?',commonMistakes:['assuming equal angles alone make every polygon similar','ignoring side proportions','assuming orientation changes angle correspondence']},
  {title:'NERDC figure types: triangles, rectangles and squares',terms:[['plane figure','flat two-dimensional shape']],explain:'NERDC names triangles, rectangles and squares explicitly. All squares are similar because every angle is90° and side ratio within each square is1:1. Rectangles require equal length:width proportion. Triangles require consistent correspondence.',example:'Squares side4 and10 have k=10/4=2.5. Rectangles3×4 and6×8 have k=2.',check:'Which is similar to a5×8 rectangle:10×16 or10×15?',commonMistakes:['assuming all triangles are similar','assuming all rectangles are similar','comparing area before checking length proportions']},
  {title:'NERDC solid types: cubes and cuboids',terms:[['solid figure','three-dimensional object'],['corresponding edges','matching lengths on similar solids']],explain:'All cubes are similar because each has edge ratio1:1:1. Cuboids are similar only when length, width and height all scale by the same factor.',example:'Cuboids2×3×5 and4×6×10 are similar with k=2. Cuboids2×3×5 and4×6×8 are not.',check:'Are cuboids3×4×6 and6×8×12 similar?',commonMistakes:['assuming all cuboids are similar','checking only length and width','comparing volumes to decide before checking dimensions']},
  {title:'Similarity in the environment',terms:[['scale model','representation preserving proportions at a different size']],explain:'NERDC requires learners to identify similarity around them. Examples include a correctly proportioned photograph and its enlargement, architectural models, maps, scaled drawings, and same-design containers manufactured in different sizes.',example:'A photograph enlarged from10×15 cm to20×30 cm preserves a scale factor2 and is similar.',check:'Explain why stretching only the width of a photograph destroys similarity.',commonMistakes:['calling any same-category objects similar','ignoring distortion','assuming same design guarantees exact mathematical similarity']},
  {title:'Meaning and direction of scale factor',terms:[['scale factor k','ratio of an image corresponding length to the original corresponding length']],explain:'Choose a direction and keep it. If original length4 becomes image10, k=10/4=5/2. Reversing direction gives2/5. State which transformation you mean.',example:'Small→large:6 cm→15 cm gives k=15/6=5/2. Large→small gives2/5.',check:'A side8 cm is enlarged to12 cm. Find k.',commonMistakes:['writing the reciprocal unintentionally','mixing direction between steps','subtracting lengths instead of dividing']},
  {title:'Enlargement and reduction',terms:[['enlargement','similar transformation with k>1'],['reduction','similar transformation with0<k<1']],explain:'k>1 makes every corresponding length larger;0<k<1 makes it smaller; k=1 preserves size. The shape remains similar in each case.',example:'k=3 changes a4 cm side to12 cm. k=1/2 changes it to2 cm.',check:'Classify k=0.4,k=1,k=2.5.',commonMistakes:['calling every scale change enlargement','using negative scale factors in this elementary size context','adding k instead of multiplying']},
  {title:'Enlarging a plane figure by lengths',terms:[['image length','original corresponding length multiplied by k']],explain:'Multiply EVERY linear dimension by the same k. If one side is missed, the result is distorted and not similar.',example:'A triangle has sides3,4,5 cm. At k=2.5 its image sides are7.5,10,12.5 cm.',check:'Enlarge a rectangle4×7 cm by k=3.',commonMistakes:['multiplying only one dimension','using k² on lengths','rounding exact simple products']},
  {title:'Reduction by a fractional scale factor',terms:[['fractional scale factor','positive factor below1 used for reduction']],explain:'The same rule works: image=original×k. Fractions and decimals below1 reduce lengths.',example:'A12×18 cm rectangle reduced by k=2/3 becomes8×12 cm.',check:'Reduce sides15,21,24 cm by k=1/3.',commonMistakes:['dividing by k when k is already image/original','subtracting one-third','treating a fractional k as invalid']},
  {title:'Coordinate enlargement about the origin',terms:[['origin','point(0,0)'],['coordinate image','new point after transformation']],explain:'For an enlargement centred at the origin, multiply both coordinates by k: (x,y)→(kx,ky). This produces a precise construction of a scaled figure.',example:'At k=2, A(1,2),B(3,1),C(1,4) become A′(2,4),B′(6,2),C′(2,8).',check:'At k=3, find the image of(−2,4).',commonMistakes:['multiplying only x','adding k to coordinates','losing negative coordinate signs']},
  {title:'Finding an unknown corresponding length',terms:[['proportion equation','equality of corresponding ratios']],explain:'Once k is known, multiply the matching original length. Alternatively set equal ratios. Always match corresponding sides.',example:'△ABC~△PQR. AB=6,PQ=9,AC=8. k=9/6=3/2, so PR=8×3/2=12.',check:'A small side10 corresponds to large side15. What does a small side14 become?',commonMistakes:['using a non-corresponding known side','adding the difference5','reversing k']},
  {title:'Finding a missing original length',terms:[['inverse scaling','dividing an image length by k to recover original']],explain:'If image=k×original, then original=image/k. This is essential when the larger figure is given and the smaller dimension is missing.',example:'k=5/2 and image length20 cm: original=20÷(5/2)=8 cm.',check:'An enlargement k=3 has image side27 cm. Find original side.',commonMistakes:['multiplying again instead of dividing','taking reciprocal incorrectly','forgetting units']},
  {title:'Perimeters of similar figures',terms:[['perimeter factor','same as the linear scale factor k']],explain:'Perimeter is a sum of lengths. Since every length is multiplied by k, the whole perimeter is multiplied by k—not k².',example:'A similar figure with k=3 and original perimeter18 cm has perimeter54 cm.',check:'Small perimeter25 cm, k=1.6. Find large perimeter.',commonMistakes:['using k² because perimeter surrounds an area','scaling only some sides','confusing perimeter with area']},
  {title:'Why areas scale by k²',terms:[['area factor','ratio of corresponding areas, equal to k²']],explain:'Area has two linear dimensions. If both are multiplied by k, their product is multiplied by k×k=k². NERDC explicitly requires the relationship length ratio1:k → area ratio1:k².',example:'Rectangle3×5 has area15. At k=2 dimensions6×10, area60=15×4. Area factor=2²=4.',check:'If k=3, by what factor does area change?',commonMistakes:['using k for area','using2k instead of k²','squaring the original area rather than the scale factor']},
  {title:'Calculating an enlarged area',terms:[['corresponding area','area of the matching similar figure']],explain:'Find linear k, square it, then multiply the original area by k².',example:'Two similar triangles have corresponding sides4 cm and10 cm. k=10/4=5/2. If small area24 cm², large area=24×25/4=150 cm².',check:'k=3/2 and small area40 cm². Find large area.',commonMistakes:['multiplying area by3/2 only','squaring area40','forgetting square units']},
  {title:'Calculating a reduced area',terms:[['area reduction factor','k² where0<k<1']],explain:'For reduction, k² is also below1. Apply it directly in the chosen direction.',example:'A shape reduced by k=1/2 from area80 cm² has new area80×1/4=20 cm².',check:'Area144 cm² is reduced with k=2/3. Find new area.',commonMistakes:['using reciprocal because result seems small','using k³','forgetting that area shrinks faster than length']},
  {title:'Working backwards: area ratio to length ratio',terms:[['square root','inverse operation of squaring']],explain:'If area factor=k², then k=√(area factor). For area ratio9:25, the corresponding positive length ratio is3:5.',example:'Areas are64 cm² and100 cm². Area ratio16:25 after simplification, so length ratio4:5.',check:'Areas of similar figures are49:81. Find length ratio.',commonMistakes:['using area ratio directly as length ratio','dividing by2 instead of square-rooting','forgetting ratio direction']},
  {title:'Why volumes scale by k³',terms:[['volume factor','ratio of corresponding volumes, equal to k³']],explain:'Volume has three linear dimensions. If length,width,height each scale by k, volume scales by k×k×k=k³. NERDC explicitly requires length ratio1:k → volume ratio1:k³.',example:'Cube edge2 cm has volume8 cm³. At k=3, edge6 cm and volume216 cm³=8×27.',check:'If k=2, by what factor does volume change?',commonMistakes:['using k² for volume','cubing the original volume','forgetting cubic units']},
  {title:'Calculating volume of a similar solid',terms:[['similar solids','3D shapes with all corresponding linear dimensions in one ratio']],explain:'Determine k from corresponding edges, cube it, and multiply volume.',example:'Similar cuboids have corresponding lengths6 and9, so k=3/2. Small volume80 cm³; large=80×(3/2)³=80×27/8=270 cm³.',check:'k=2.5 and small volume32 cm³. Find large volume.',commonMistakes:['using length factor directly on volume','using area factor','failing to cube a fraction correctly']},
  {title:'Working backwards: volume ratio to length ratio',terms:[['cube root','inverse operation of cubing']],explain:'If volume factor=k³, recover k with the positive cube root. Volume ratio8:125 gives length ratio2:5.',example:'Similar cubes have volumes64:216. Cube roots give edge ratio4:6=2:3.',check:'Volumes are27:343. Find corresponding length ratio.',commonMistakes:['taking square root','using volume ratio unchanged','cube-rooting only one side']},
  {title:'Area factor versus volume factor',terms:[['dimensional scaling','different powers of k arising from number of dimensions']],explain:'Length/perimeter use k; area/surface area use k²; volume uses k³. Learn the reason, not just the formula. If k=4, length×4, area×16, volume×64.',example:'For k=1/2: length factor1/2, area1/4, volume1/8.',check:'For k=3, state all three factors.',commonMistakes:['interchanging k² and k³','assuming everything changes by k','forgetting surface area is an area']},
  {title:'Similar squares',terms:[['square','quadrilateral with four equal sides and four right angles']],explain:'All squares are similar. Side ratio gives k directly; area ratio is the square of side ratio.',example:'Sides6 and15: k=15/6=5/2; area ratio large:small=25:4.',check:'Squares have side ratio3:7. Find area ratio.',commonMistakes:['using perimeter ratio for area','assuming area ratio3:7','squaring only one ratio term']},
  {title:'Similar rectangles',terms:[['aspect ratio','ratio of length to width']],explain:'Rectangles are similar only if their aspect ratios match. Then all lengths share the same k.',example:'4×6 and10×15:4/6=10/15=2/3, so similar; k=10/4=2.5.',check:'Are6×9 and10×15 similar?',commonMistakes:['all rectangles have right angles so must be similar','matching long side to short side inconsistently','checking area only']},
  {title:'Similar triangles and proportional sides',terms:[['side correspondence','matching triangle sides according to vertices/angles']],explain:'Once triangles are known similar, proportional sides solve unknown lengths. Keep the correspondence order explicit.',example:'△ABC~△DEF, AB=5,DE=8,BC=7. Then EF=7×8/5=56/5=11.2.',check:'If AB:DE=3:5 and AC=9, find DF.',commonMistakes:['using5/3 in one step and3/5 in another','matching BC with DF accidentally','rounding before final answer']},
  {title:'Similar cubes',terms:[['edge factor','linear scale factor between cube edges']],explain:'For cubes, edge ratio=k, surface-area ratio=k², volume ratio=k³. Because all edges in each cube are equal, correspondence is straightforward.',example:'Edges3 and6 give k=2; surface areas ratio1:4; volumes ratio1:8.',check:'Cube edges5 and15: find area and volume ratios small:large.',commonMistakes:['squaring for volume','cubing for surface area','comparing numerical areas without maintaining direction']},
  {title:'Similar cuboids',terms:[['dimension ratio','common ratio among length,width,height']],explain:'A cuboid is similar only when all three corresponding dimensions scale equally. Then volume factor follows k³.',example:'6×3×5 enlarged to length14 has k=14/6=7/3. Similar dimensions must be14×7×35/3.',check:'A4×6×10 cuboid is enlarged with k=1.5. Find dimensions.',commonMistakes:['scaling only length','rounding35/3 unnecessarily','assuming same volume ratio proves similarity']},
  {title:'Units before similarity calculations',terms:[['unit consistency','expressing comparable quantities in matching units']],explain:'Corresponding length ratios require the same units. Convert before forming k. Area conversions are squared and volume conversions cubed, so converting linear units first is often safest.',example:'2 m corresponds to50 cm. Convert2 m=200 cm, so k=50/200=1/4 in that direction.',check:'A model length12 cm represents3 m. Find model:actual linear ratio.',commonMistakes:['forming12/3 without unit conversion','using100 instead of10000 for m²↔cm²','mixing units inside one ratio']},
  {title:'Scale models and maps',terms:[['scale','stated model/drawing length compared with real length']],explain:'A scale1:n means1 unit on model represents n of the same units in reality. It is a linear ratio; area and volume comparisons require squaring or cubing when applicable.',example:'Scale1:20, actual car length4 m=400 cm. Model length=400/20=20 cm.',check:'At scale1:50, a real length10 m is how long on the model in cm?',commonMistakes:['forgetting same units','multiplying when converting actual to smaller model','using1:50 directly as area ratio']},
  {title:'Environmental enlargement without distortion',terms:[['distortion','change of proportions so figures cease to be similar']],explain:'If horizontal and vertical dimensions use different factors, the image is stretched and not mathematically similar. Similarity requires one common linear scale factor.',example:'10×15 photo→20×30 uses k=2 and is similar. 10×15→20×25 uses factors2 and5/3, so it is distorted.',check:'Is8×12 enlarged to12×18 similar?',commonMistakes:['checking only width','assuming digital resizing always preserves similarity','ignoring differing factors']},
  {title:'Quantitative reasoning with area and cost',terms:[['area-proportional quantity','quantity assumed in the problem to change directly with area']],explain:'Some BECE-style reasoning links cost/material to area. First establish that the context makes cost proportional to area, then apply k².',example:'Similar trays: lengths40 cm and50 cm, k=5/4. If cost is proportional to area and small costs ₦256, large cost=256×25/16=₦400.',check:'A similar sheet enlarged with k=3/2 costs ₦800 when cost is proportional to area. Find enlarged cost.',commonMistakes:['assuming every cost always scales with area','using k instead of k² when area proportionality is stated','ignoring fixed costs in contexts where proportionality is not given']},
  {title:'Quantitative reasoning with volume and capacity',terms:[['capacity','amount a container can hold, related to internal volume']],explain:'For geometrically similar containers, capacity scales with k³ if wall effects are ignored as the problem intends.',example:'A small similar container holds2 L. If large linear dimensions are twice as large, k=2 and capacity=2×8=16 L.',check:'A model tank has volume5 L and actual linear scale is3 times. Find corresponding volume.',commonMistakes:['using k²','multiplying by3 only','assuming containers are similar without statement/evidence']},
  {title:'Reverse mixed problem from area to volume',terms:[['derived factor','one scaling factor obtained from another']],explain:'Sometimes area information gives k, then volume is required. First square-root area factor to get k; then cube k for volume factor.',example:'Similar solids have surface-area ratio9:25. Linear ratio=3:5. Volume ratio=27:125.',check:'Surface-area ratio16:49. Find volume ratio.',commonMistakes:['cubing9:25 directly','using area ratio as k','taking cube root before square root']},
  {title:'Reverse mixed problem from volume to area',terms:[['cross-dimensional scaling','moving between volume, length and area factors through k']],explain:'From volume factor obtain k by cube root; then square k to get area factor.',example:'Volume ratio8:27→length ratio2:3→area ratio4:9.',check:'Volume ratio64:125. Find area ratio.',commonMistakes:['square-rooting volume ratio','using8:27 as area ratio','mixing ratio direction']},
  {title:'BECE-style missing-length problem',terms:[['proportional equation','equation equating matching side ratios']],explain:'Write correspondence before numbers. If small/large=a/b=c/x, solve by valid multiplication. Avoid visual guessing.',example:'Similar triangles: small sides6 and8 correspond to large9 and x. 6/9=8/x→6x=72→x=12.',check:'Small side5 corresponds to large8; small side7.5 corresponds to x. Find x.',commonMistakes:['pairing6 with x','adding3 to every side','cross-multiplying inconsistent ratios']},
  {title:'BECE-style area problem',terms:[['area ratio','square of corresponding length ratio']],explain:'Use exact fractions where possible. If length ratio small:large=2:5, area ratio=4:25.',example:'Small area36 cm², side ratio small:large=3:5. Large area=36×25/9=100 cm².',check:'Small:large side ratio4:7; large area196 cm². Find small area.',commonMistakes:['multiplying36 by5/3','reversing25/9','forgetting cm²']},
  {title:'BECE-style volume problem',terms:[['volume ratio','cube of corresponding length ratio']],explain:'Cube both terms of the linear ratio, then use proportion.',example:'Small:large edge ratio2:3; small volume64 cm³. Large=64×27/8=216 cm³.',check:'Small:large length ratio3:5; large volume1000 cm³. Find small volume.',commonMistakes:['squaring instead of cubing','reversing ratio','using linear dimensions from non-similar solids']},
  {title:'Error diagnosis: using k for area',terms:[['dimensional error','using the wrong power of scale factor']],explain:'If k=3 and a student triples area, ask what happened to both dimensions. Each multiplied by3, so area must multiply by9.',example:'Original area20 cm²,k=3→new area180 cm², not60 cm².',check:'Correct the claim: “k=2, so volume doubles.”',commonMistakes:['memorizing without dimensional reasoning','correcting number but not explaining why','confusing surface area and volume']},
  {title:'Error diagnosis: wrong correspondence',terms:[['ratio consistency','using matching quantities in the same directional order']],explain:'A correct formula with wrong side correspondence still gives a wrong answer. Label matching vertices or dimensions before ratio work.',example:'If AB↔PQ and AC↔PR, use AB/PQ=AC/PR, not AB/PR=AC/PQ.',check:'Explain why correspondence should be written before substituting numbers.',commonMistakes:['trusting diagram orientation','matching longest to longest without labels when not justified','changing ratio direction mid-equation']},
  {title:'Final mastery routine for Similar Shapes',terms:[['similarity workflow','ordered checks for solving similarity problems']],explain:'Use: identify figure type; establish correspondence; verify similarity if required; state ratio direction; calculate k; decide whether target is length/perimeter(k), area(k²), or volume(k³); convert units; solve; attach correct units; check whether enlargement/reduction makes sense. For reverse problems, root the area/volume factor first.',example:'Area factor25/9→k=5/3. If original corresponding length12 cm, image=20 cm. If original volume54 cm³, image=54×125/27=250 cm³.',check:'Why is identifying the dimension of the requested quantity essential before using k?',commonMistakes:['using one power of k for every quantity','omitting units','not checking direction or reasonableness']
  }
 ]
};

