export const jss3ChangeSubjectTopic='Change of Subject of Formulae (addition, multiplication, division and roots)';
export const jss3ChangeSubjectPlan:TutorPlan={goal:'Rearrange formulae so a required variable stands alone while preserving equality.',why:'Changing the subject is inverse-operation reasoning: whatever is done to one side must preserve an equivalent relationship.',outcomes:['Identify the current subject of a formula.','Change subject through addition/subtraction.','Change subject through multiplication/division.','Change subject when powers and roots are involved.','Handle brackets and fractions safely.','Substitute values to verify rearrangements.'],examFocus:['Identify the target variable before moving anything.','Undo operations in reverse order.','Operate on both sides, not by unexplained “crossing”.','Clear fractions carefully.','Use square root when undoing a square and consider the context for sign.','Verify by substitution where practical.'],units:[
{title:'Meaning of the subject of a formula',terms:[['formula','equation connecting quantities'],['subject','variable isolated alone on one side']],explain:'In v=u+at, v is the subject because v stands alone. Changing subject means producing an equivalent formula with another named variable isolated.',example:'A=lw has A as subject; l=A/w changes subject to l.',check:'What is the subject of P=2(l+w)?',commonMistakes:['subject means first letter','ignore equality','change values instead of variable']},
{title:'Undo addition and subtraction',terms:[['inverse operations','operations that undo each other']],explain:'To isolate a term added to something, subtract the other term from both sides; to undo subtraction, add.',example:'v=u+at, target u: v−at=u, so u=v−at.',check:'Make x subject of y=x+c.',commonMistakes:['change sign without equality reasoning','subtract wrong term','target not isolated']},
{title:'Undo multiplication and division',terms:[['coefficient','multiplier of a variable']],explain:'If target is multiplied by a nonzero quantity, divide both sides by it. If target is in a numerator divided by a quantity, multiply both sides.',example:'A=bh, target h→h=A/b. y=x/k, target x→x=ky.',check:'Make m subject of F=ma.',commonMistakes:['multiply instead of divide','divide only one term','ignore zero restrictions']},
{title:'Brackets and multi-step rearrangement',terms:[['reverse order','undo outermost operation before inner operation']],explain:'Treat a bracketed expression as one unit. In P=2(l+w), first divide by2, then subtract l: P/2=l+w→w=P/2−l.',example:'y=3(x−4): y/3=x−4→x=y/3+4.',check:'Make x subject of a=5(x+2).',commonMistakes:['expand unnecessarily then lose terms','subtract before dividing when it changes structure incorrectly','forget bracket grouping']},
{title:'Formulae with fractions',terms:[['clearing denominator','multiplying both sides by a denominator']],explain:'If target occurs in a fraction, clear denominators systematically before isolating it.',example:'v=d/t, target t: vt=d→t=d/v. For y=(x+a)/b: by=x+a→x=by−a.',check:'Make r subject of C=2πr.',commonMistakes:['informal cross multiplication errors','denominator left attached','wrong sign']},
{title:'Squares and square roots',terms:[['square root','inverse operation of squaring']],explain:'If target is squared, isolate the square first, then take square root. In geometric contexts lengths are normally positive; algebraically ± may matter depending on the formula/context.',example:'A=πr²→r²=A/π→r=√(A/π) for a radius.',check:'Make x subject of y=x²+3 for a context where x≥0.',commonMistakes:['divide exponent by2','√ only one factor incorrectly','forget context/sign']},
{title:'Roots containing the target',terms:[['squaring both sides','inverse step used to remove a square root']],explain:'If y=√(x+a), square both sides: y²=x+a, then x=y²−a.',example:'v=√(2gh), target h: v²=2gh→h=v²/(2g).',check:'Make x subject of y=√(3x+1).',commonMistakes:['square only y but not relationship','forget bracket under root','divide before removing root']},
{title:'Changing the subject when the target is inside a fraction',terms:[['numerator','expression above a fraction bar'],['denominator','expression below a fraction bar']],outcomes:['clear a denominator before isolating the target','show equivalent equations line by line'],explain:'Do not use the phrase “cross multiply” as a magic move. State what operation is performed on both sides. If y=(2x+3)/5, multiply both sides by 5 first because the whole numerator is divided by 5.',example:'Make x the subject of y=(2x+3)/5.\n\n        2x+3\ny =     -----\n          5\n\nMultiply BOTH sides by 5:\n5y = 2x+3\n\nSubtract 3 from BOTH sides:\n5y-3 = 2x\n\nDivide BOTH sides by 2:\n      5y-3\nx =   -----\n        2\n\nEvery line is equivalent to the previous line.',check:'Make x the subject of p=(3x-4)/7.',commonMistakes:['move 5 across without explaining the operation','divide only one term in the numerator','lose the minus sign']},
{title:'Target in a denominator',terms:[['non-zero restriction','a denominator cannot equal zero']],outcomes:['rearrange a formula with the target in the denominator','state necessary non-zero conditions'],explain:'When the target is in a denominator, first multiply both sides by that denominator. Then isolate the target. Keep the equality visible at every step.',example:'Make t the subject of v=d/t.\n\n     d\nv = ---\n     t\n\nMultiply both sides by t:\nvt=d\n\nDivide both sides by v:\n    d\nt = --- , v≠0\n    v\n\nCheck: substituting t=d/v into d/t gives d÷(d/v)=v for valid non-zero values.',check:'Make r the subject of q=p/r.',commonMistakes:['write t=dv','invert the wrong quantity','forget that division by zero is invalid']},
{title:'Formula with a bracket and an outside divisor',terms:[['outer operation','last operation applied to the target-containing expression']],outcomes:['undo operations from outside inward','preserve bracket grouping'],explain:'Identify what happened to the target-containing bracket last. Undo that operation first. This prevents random sign changes and unnecessary expansion.',example:'Make x the subject of y=[3(x-2)]/4.\n\n        3(x-2)\ny =     -------\n           4\n\nMultiply both sides by 4:\n4y=3(x-2)\n\nDivide both sides by 3:\n4y/3=x-2\n\nAdd 2 to both sides:\n       4y\nx = 2 + --\n        3',check:'Make x the subject of a=2(x+5)/7.',commonMistakes:['add 2 before clearing the outside operations','drop the bracket','change signs by “moving” terms without an inverse operation']},
{title:'Formula containing a square',terms:[['principal square root','non-negative square root used for a physical length']],outcomes:['isolate a squared target','take the appropriate square root','interpret sign from context'],explain:'A square cannot be removed by dividing by 2. First isolate the squared expression; then apply a square root. In a length formula the positive root is normally required.',example:'Make r the subject of A=πr².\n\nA=πr²\n\nDivide both sides by π:\nA/π=r²\n\nTake the positive square root because radius is a length:\n      _____\nr = \/ A/π\n\nThe square root undoes the square; “r=A/(2π)” would be a different operation and is wrong.',check:'Make h the subject of E=mgh² for h≥0.',commonMistakes:['divide the exponent by 2','take the square root before isolating the square','ignore whether the context permits a negative root']},
{title:'Verification and final workflow',terms:[['equivalent formula','rearranged formula true for the same valid values']],explain:'Mark target; identify outer operations; undo them in reverse using both sides; simplify; verify by substituting a simple valid set of values into original and rearranged forms.',example:'P=2(l+w), P=20,l=6 gives w=4. Rearranged w=P/2−l=10−6=4.',check:'State the full method for changing the subject.',commonMistakes:['symbol shuffling','target still on both sides unnecessarily','no check']}
]};
