{id:'jss3-csf-19',prompt:'Changing the subject should produce:',options:['an equivalent formula','a different physical law','a numerical answer always','a graph only'],correctAnswer:'an equivalent formula',explanation:'The relationship is preserved.',difficulty:1,skill:'concept'},
{id:'jss3-csf-20',prompt:'Which is the strongest workflow?',options:['target→identify outer operations→undo on both sides→simplify→verify','change signs→guess→stop','substitute before reading target','erase denominators'],correctAnswer:'target→identify outer operations→undo on both sides→simplify→verify',explanation:'This is controlled inverse-operation reasoning.',difficulty:1,skill:'mastery'}
