export const jss3ElevationDepressionTopic='Angles of Elevation and Depression (trigonometric ratios, clinometer and distance/height estimation)';
export const jss3ElevationDepressionPlan:TutorPlan={goal:'Apply right-triangle trigonometry to angles of elevation/depression and understand how a clinometer supports practical distance/height estimation.',why:'This topic turns the earlier trigonometric ratios into field measurement: a horizontal reference line, line of sight and vertical/horizontal distances form a right-triangle model.',outcomes:['Distinguish elevation from depression.','Relate horizontal lines using alternate angles.','Use sine/cosine/tangent to find heights/distances.','Include observer/instrument height when appropriate.','Explain basic clinometer use and measurement assumptions.','Solve practical BECE-style problems.'],examFocus:['Draw a horizontal reference through the observer.','Elevation is measured upward from horizontal; depression downward.','Parallel horizontals make relevant alternate angles equal.','Label O/A/H relative to the stated angle.','Add/subtract eye or instrument height only when the geometry requires it.','State units and reasonable assumptions such as level ground.'],units:[
{title:'Angle of elevation',terms:[['angle of elevation','angle measured upward from a horizontal line to a line of sight']],explain:'Stand at the observer and draw a horizontal reference. If the object is above that line, the angle from horizontal upward to the line of sight is the angle of elevation.',example:'Looking from eye level to the top of a tower gives an upward line of sight; the angle at the observer is elevation.',check:'From what reference line is elevation measured?',commonMistakes:['measure from vertical','place angle at object top','confuse with depression']},
{title:'Angle of depression',terms:[['angle of depression','angle measured downward from a horizontal line to a line of sight']],explain:'If the target is below the observer’s horizontal line, measure downward from that horizontal to the line of sight.',example:'From the top of a building looking down at a car, the angle below the top horizontal is depression.',check:'Where is the depression angle located in the standard diagram?',commonMistakes:['measure at ground target','use vertical reference','call every downward angle elevation']},
{title:'Why elevation and depression angles can be equal',terms:[['alternate angles','equal angles formed when a transversal crosses parallel lines']],explain:'Horizontal lines through observer and target level are parallel. The line of sight is a transversal, so the angle of depression at the top equals the corresponding/alternate elevation angle at the lower point in the standard level-ground model.',example:'If depression from tower top to car is35°, the elevation from car to tower top is35°.',check:'What geometric fact justifies using the same35°?',commonMistakes:['assume equality without parallel horizontals','use complementary angle','mix angle with90°']},
{title:'Height from distance and elevation',terms:[['horizontal distance','adjacent side'],['vertical rise','opposite side']],explain:'With horizontal distance d and elevation θ, tanθ=rise/d, so rise=d tanθ.',example:'d=30 m,θ=40°→rise≈30tan40°≈25.17 m.',check:'d=20 m,θ=35°. Find vertical rise.',commonMistakes:['sine without hypotenuse','distance as hypotenuse','wrong calculator mode']},
{title:'Distance from height and elevation',terms:[['adjacent unknown','horizontal distance found from O/tanθ']],explain:'tanθ=height/distance, so distance=height/tanθ when the vertical rise is known.',example:'Tower rise18 m, elevation30°→distance=18/tan30°≈31.18 m.',check:'Rise12 m,elevation45°. Find distance.',commonMistakes:['multiply by tangent','use total tower height when eye-height adjustment applies','radian mode']},
{title:'Observer or instrument height',terms:[['instrument height','height of eye/clinometer above ground']],explain:'Trigonometry gives vertical difference between instrument level and target. For total object height on level ground, add instrument height when sighting the top from above ground.',example:'Clinometer1.5 m high, distance25 m,elevation32°: rise≈15.62 m; total≈17.12 m.',check:'Why is1.5 m added after the tangent calculation?',commonMistakes:['add before tangent','forget height','double-count when opposite already represents total']},
{title:'Using a clinometer',terms:[['clinometer','instrument for measuring an angle of elevation/depression relative to horizontal']],explain:'A simple clinometer provides the sight angle. Measure horizontal distance separately, note instrument/eye height, sight the target, read θ, then build the right-triangle model. Repeated measurements improve reliability.',example:'Distance40 m, clinometer elevation28°, instrument height1.4 m→rise=40tan28°≈21.27 m; total≈22.67 m.',check:'What measurements besides θ are needed to estimate height with tangent?',commonMistakes:['clinometer directly gives height','ignore level ground/distance','measure sloping ground distance as horizontal without adjustment']},
{title:'Angle of depression practical problem',terms:[['line of sight','straight line from observer to target']],explain:'Translate depression to the equal elevation angle when horizontals are parallel, then use the right triangle.',example:'From a20 m platform, depression to a point on level ground is45°. Horizontal distance=20/tan45°=20 m.',check:'Height30 m,depression60°. Find horizontal distance.',commonMistakes:['use60° from vertical','forget equality of horizontal-reference angles','wrong side labels']},
{title:'Draw the triangle before choosing a ratio',terms:[['reference horizontal','level line through the observer used to measure elevation/depression'],['vertical','line perpendicular to the horizontal']],outcomes:['convert a word problem into a labelled right triangle','identify opposite, adjacent and hypotenuse relative to the stated angle'],explain:'The words do not tell you automatically which trigonometric ratio to use. Draw the horizontal, vertical object and line of sight first. Mark the given angle. Only then label O, A and H relative to that angle.',example:'Observer P is 40 m from the foot B of a vertical tower BT and sees top T at 35°.\n\n             T\n             |\\\n             | \\  line of sight (H)\n height (O)  |  \\\n             |   \\\n             B----P\n              40 m (A)\n                   35°\n\nRelative to 35° at P: tower height BT is opposite; PB is adjacent. Therefore tangent is appropriate because tanθ=O/A.',check:'A tree is viewed from 25 m away at 42°. Identify O, A and H before choosing a ratio.',commonMistakes:['choose tangent before identifying sides','put the angle at the foot of the object','treat horizontal distance as the hypotenuse']},
{title:'Worked height example with every calculator step',terms:[['DEG mode','calculator setting for angles measured in degrees']],outcomes:['form the tangent equation','isolate the unknown height','use a calculator result sensibly'],explain:'Once the diagram shows opposite height h and adjacent distance d, write the ratio in symbols before inserting numbers. This makes the method visible and reduces calculator guessing.',example:'A pole is observed from 18 m away at an elevation of 37°. Find the vertical rise from eye level.\n\nStep 1: O=h, A=18.\nStep 2: tan37°=h/18.\nStep 3: Multiply both sides by 18:\nh=18tan37°.\nStep 4: In DEG mode, tan37°≈0.7536.\nStep 5: h≈18×0.7536≈13.56 m.\n\nReasonableness: 37° is below 45°, so for the same horizontal distance the opposite side should be shorter than 18 m. 13.56 m is reasonable.',check:'From 30 m away, the elevation to a roof is 28°. Find the rise above eye level.',commonMistakes:['calculator in radians','write tanθ=A/O','round too early']},
{title:'Two-stage height with eye level',terms:[['vertical rise','height from observer eye/instrument level to target'],['total height','vertical rise plus observer/instrument height when ground levels match']],outcomes:['distinguish calculated rise from total object height','add eye height only after the trigonometric calculation'],explain:'The horizontal sight line begins at the observer’s eye, not at the ground. Therefore the opposite side in the small right triangle is the height above eye level. On level ground, add eye height afterwards to obtain total height.',example:'A student whose eye is 1.6 m above level ground stands 24 m from a tree. Elevation to the top is 34°.\n\nRise above eye level:\ntan34° = h/24\nh = 24tan34° ≈ 16.19 m.\n\nTotal tree height:\nH = 16.19+1.60 = 17.79 m ≈ 17.8 m.\n\nWe did NOT put 1.6 inside the tangent ratio because 24 m and 34° describe the triangle beginning at eye level.',check:'Eye height is 1.5 m, distance 20 m, elevation 40°. Find total object height.',commonMistakes:['forget eye height','add eye height before calculating the rise','add eye height when the given opposite side already represents total height']},
{title:'Depression converted to an elevation triangle',terms:[['parallel horizontals','level lines that never meet'],['alternate angle','equal angle produced by a transversal across parallel lines']],outcomes:['transfer a depression angle correctly','solve the resulting right triangle'],explain:'An angle of depression is drawn at the upper observer. For calculation, it is often convenient to use the equal angle of elevation at the lower target. This equality comes from parallel horizontal lines crossed by the same line of sight.',example:'From the top T of a 30 m building TB, a car C is seen at an angle of depression 50°.\n\nTop horizontal ---- T\n                    |\\ 50° downward line of sight\n               30 m | \\\n                    |  \\\n                    B---C\n                         50° elevation\n\nAt C, tan50°=30/BC.\nTherefore BC=30/tan50°≈25.17 m.\nThe 50° at C is justified by the parallel horizontals; it is not guessed.',check:'From a 24 m cliff, depression to a boat is 38°. Find the horizontal distance to the boat.',commonMistakes:['use 40° or another complement without reason','place depression at the lower target initially','divide/multiply by tangent in the wrong direction']},
{title:'Final elevation/depression workflow',terms:[['field-trig workflow','horizontal→line of sight→θ→O/A/H→ratio→adjust height→check']],explain:'Draw the scene; add horizontal reference; mark elevation/depression at correct location; transfer equal angle if justified; label vertical/horizontal/hypotenuse; choose ratio; solve in DEG mode; include instrument height if needed; state assumptions and units.',example:'Never choose tangent just because “tower” appears; choose it because O and A are the known/required pair.',check:'State the workflow for a clinometer height problem.',commonMistakes:['diagram omitted','angle at wrong point','automatic tangent without side analysis','no units']}
]};
